#pragma once
static void checkExplicitHydrogenExpansion(App& app,const std::string& dir){
    auto require=[](bool ok,const std::string& why){if(!ok)throw std::runtime_error("explicit hydrogens: "+why);};auto& s=app.s;
    auto reset=[&](const Document& doc,ObjectId host){s.cancel();s.doc=doc;s.history.clear();s.selected={{ObjectKind::Atom,host}};s.input.bindDocument(s.doc.id());s.refresh();app.expandPending=false;};
    int cases=0;
    for(int kind=0;kind<10;++kind){Document d;d.setDefaultBondLength(30);ObjectId host;std::vector<ObjectId> fixed;
        if(kind==0){for(int i=0;i<6;++i){ObjectId id;d.addAtom(Vec2(120+30*std::cos(i*3.141592653589793/3),100+30*std::sin(i*3.141592653589793/3)),6,&id);fixed.push_back(id);}for(int i=0;i<6;++i)d.addBond(fixed[i],fixed[(i+1)%6],nullptr);host=fixed[0];}
        else{int element=kind<=2?6:kind<=5?7:kind==6?8:kind==7?16:kind==8?14:7;d.addAtom(Vec2(120,100),element,&host);fixed.push_back(host);int neighbors=kind==1?3:kind==2?2:kind==4?2:kind==9?0:1;for(int i=0;i<neighbors;++i){ObjectId id;double angle=neighbors==3?90+i*120:neighbors==2?i*180:180;d.addAtom(Vec2(120,100)+core::direction(angle)*30,6,&id);d.addBond(host,id,nullptr);fixed.push_back(id);}auto sem=d.atoms().alive(host)->semantics;sem.implicitHydrogens=kind==1?1:kind==2?2:kind==3?2:kind==4?1:kind==5?3:kind==6||kind==7?1:kind==8?3:4;if(kind==5||kind==9)sem.charge=1;if(kind==2)sem.isotope=13;d.setAtomSemantics(host,sem);if(kind==2)d.setAtomLabel(host,"CH2");if(kind==3)d.setAtomLabel(host,"NH2");if(kind==4)d.setAtomLabel(host,"NH");if(kind==6)d.setAtomLabel(host,"OH");if(kind==7)d.setAtomLabel(host,"SH");if(kind==8)d.setAtomLabel(host,"SiH3");}
        int expected=kind==0?2:kind==1?1:kind==2||kind==3?2:kind==4?1:kind==5?3:kind==6||kind==7?1:kind==8?3:4;reset(d,host);auto before=s.doc.digest();auto count=s.doc.stats().aliveAtoms;auto formula=studio::analyze(s.doc,s.all()).plain;app.expandGroups();require(s.doc.stats().aliveAtoms==count+expected,"expand requested H count kind="+std::to_string(kind)+": "+app.status);require(s.doc.atoms().alive(host)->semantics.implicitHydrogens==0,"implicit count cleared after explicit creation");int hs=0;for(auto bid:s.doc.incidentBonds(host)){auto b=s.doc.bonds().alive(bid);auto other=b->beginAtom==host?b->endAtom:b->beginAtom;if(s.doc.atoms().alive(other)->element==1){++hs;require(std::abs(length(s.doc.atoms().alive(other)->position-s.doc.atoms().alive(host)->position)-30)<1e-6,"visible H bond at standard length");}}require(hs==expected,"every H is bonded to the selected atom");
        require(studio::analyze(s.doc,s.all()).plain==formula,"molecular formula preserved kind="+std::to_string(kind)+" "+formula+" -> "+studio::analyze(s.doc,s.all()).plain);for(auto id:fixed)require(s.doc.atoms().alive(id)->position==d.atoms().alive(id)->position,"heavy framework fixed");require(s.doc.atoms().alive(host)->semantics.charge==d.atoms().alive(host)->semantics.charge&&s.doc.atoms().alive(host)->semantics.isotope==d.atoms().alive(host)->semantics.isotope,"charge and isotope preserved");auto after=s.doc.digest();require(s.undo().ok()&&s.doc.digest()==before&&s.undo(true).ok()&&s.doc.digest()==after,"one-step undo redo");s.selected={{ObjectKind::Atom,host}};app.expandGroups();require(s.doc.digest()==after,"repeat cannot duplicate explicit H");
        if(kind==0||kind==1||kind==3){auto name=kind==0?"expanded-cyclohexane-CH2":kind==1?"expanded-branch-CH":"expanded-NH2";s.selected.clear();s.fit();app.invalidate();app.screenshot(dir+"/"+name+".png");require(s.save(dir+"/"+name+".cdxml",true).ok(),"save hydrogen example");Session back;require(back.open(dir+"/"+name+".cdxml").ok(),"reopen explicit H drawing");int hydrogens=0;for(const auto& a:back.doc.atoms().records())if(a.isAlive()&&a.element==1)++hydrogens;require(hydrogens==expected,"explicit H survives CDXML");}
        ++cases;
    }
    // Multi-selection expands each requested atom; a methyl-only selection
    // retains its established two-stage behaviour.
    Document d;d.setDefaultBondLength(30);ObjectId host,n,left;d.addAtom(Vec2(90,100),6,&host);d.addAtom(Vec2(120,100),7,&n);d.addAtom(Vec2(60,100),6,&left);d.addBond(left,host,nullptr);d.addBond(host,n,nullptr);auto sem=d.atoms().alive(host)->semantics;sem.implicitHydrogens=2;d.setAtomSemantics(host,sem);sem=d.atoms().alive(n)->semantics;sem.implicitHydrogens=2;d.setAtomSemantics(n,sem);reset(d,host);s.selected.push_back({ObjectKind::Atom,n});auto formula=studio::analyze(s.doc,s.all()).plain;app.expandGroups();require(s.doc.stats().aliveAtoms==7&&studio::analyze(s.doc,s.all()).plain==formula,"mixed CH2 and NH2 selection expands four H");
    reset(d,host);s.selected.push_back({ObjectKind::Atom,n});app.expandPending=true;app.expandDocument=s.doc.id();app.expandDigest=s.doc.digest();app.expandSelection=s.selected;app.expandGroups();require(s.doc.stats().aliveAtoms==3,"second consecutive compound expansion retains structure-cleanup action");app.expandPending=false;
    Document methyl;ObjectId c,cl;methyl.addAtom(Vec2(90,100),6,&c);methyl.addAtom(Vec2(120,100),17,&cl);methyl.addBond(c,cl,nullptr);reset(methyl,c);app.expandGroups();require(s.doc.stats().aliveAtoms==2&&s.doc.atoms().alive(c)->semantics.implicitHydrogens==3,"methyl label stage preserved");app.expandGroups();require(s.doc.stats().aliveAtoms==5,"methyl explicit stage preserved");
    Document legacy;ObjectId alias,carbon;legacy.addAtom(Vec2(90,100),6,&alias);legacy.addAtom(Vec2(60,100),6,&carbon);legacy.addBond(alias,carbon,nullptr);legacy.setAtomLabel(alias,"NH2");auto meta=legacy.atoms().alive(alias)->semantics;meta.nodeType=uint8_t(NodeType::Nickname);meta.implicitHydrogens=2;legacy.setAtomSemantics(alias,meta);legacy.extensions(ObjectRef(ObjectKind::Atom,alias)).set("studio.nickname.fragment","<fragment id=\"1\"><n id=\"2\" Element=\"7\" NumHydrogens=\"2\" p=\"0 0\"/><n id=\"3\" NodeType=\"ExternalConnectionPoint\" p=\"-30 0\"/><b id=\"4\" B=\"2\" E=\"3\" Order=\"1\"/></fragment>");reset(legacy,alias);app.expandGroups();require(s.doc.atoms().alive(alias)->element==7&&s.doc.stats().aliveAtoms==4,"legacy NH2 fragment expands its nitrogen and two H without carbon placeholder");
    // Real absolute-configuration check for a CH stereocentre after the implicit
    // hydrogen becomes a normal/wedged explicit ligand.
    std::string xml;require(chemservice::run(app.h,"(2S)-2-aminopropanoic acid","chemical/x-name","text/xml","convert",&xml),"load chiral CH");Session chiral;require(persistence::readCdxml(xml,chiral.doc).ok(),"import chiral CH");ObjectId center=kInvalidObjectId;for(const auto& a:chiral.doc.atoms().records())if(a.isAlive()&&a.element==6&&chiral.doc.incidentBonds(a.id).size()==3&&chemistry::refreshAtomDerived(chiral.doc,a.id,{}).newHydrogenCount==1)center=a.id;require(center!=kInvalidObjectId,"find stereogenic CH");reset(chiral.doc,center);auto name=[&](){std::string input,out;require(studioio::exportXml(s.doc,&input).ok(),"export stereochemistry");require(chemservice::run(app.h,input,"text/xml","chemical/x-name","convert",&out),"name stereochemistry");return out;};auto original=name();auto count=s.doc.stats().aliveAtoms;app.expandGroups();require(s.doc.stats().aliveAtoms==count+1&&name()==original,"explicit H preserves absolute stereochemical name");
    studio::explicit_hydrogens::Plan plan;legacy.extensions(ObjectRef(ObjectKind::Atom,alias)).set("studio.compound.saved","1");require(!studio::explicit_hydrogens::plan(legacy,alias,&plan),"saved whole structures restore their original graph before atomic H expansion");Document query;ObjectId generic;query.addAtom(Vec2(),6,&generic);query.setAtomLabel(generic,"BH");auto qs=query.atoms().alive(generic)->semantics;qs.nodeType=uint8_t(NodeType::Query);query.setAtomSemantics(generic,qs);query.extensions(ObjectRef(ObjectKind::Atom,generic)).set("pst.attr.MoleculeStudioRole","base");require(!studio::explicit_hydrogens::plan(query,generic,&plan),"generic base is never converted into real boron");Document unknown;ObjectId bad;unknown.addAtom(Vec2(),6,&bad);unknown.setAtomLabel(bad,"UnknownH2");require(!studio::explicit_hydrogens::plan(unknown,bad,&plan),"unknown/composite labels are not stripped");
    std::ofstream(dir+"/explicit-hydrogen-checks.json")<<"{\"cases\":"<<cases<<",\"ring_ch2\":true,\"branch_ch\":true,\"nh2_nh_oh_sh_sih3\":true,\"charged_hydrides\":true,\"isotope\":true,\"mixed_selection\":true,\"consecutive_cleanup_preserved\":true,\"legacy_nh2_alias\":true,\"saved_structure_priority\":true,\"query_role_preserved\":true,\"formula_preserved\":true,\"framework_fixed\":true,\"no_duplicate_h\":true,\"methyl_stages_preserved\":true,\"absolute_stereo\":true,\"undo_redo\":true,\"cdxml\":true}";
}
